-- Modify "order_items" table
ALTER TABLE "order_items" ADD COLUMN "delivery_source_id" bigint NULL;
-- Create index "orderitem_delivery_source_id" to table: "order_items"
CREATE INDEX "orderitem_delivery_source_id" ON "order_items" ("delivery_source_id");
-- Modify "products" table
ALTER TABLE "products" ADD COLUMN "category_protected" boolean NOT NULL DEFAULT false;
-- Create "product_delivery_sources" table
CREATE TABLE "product_delivery_sources" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "product_id" bigint NOT NULL, "sku_id" bigint NOT NULL DEFAULT 0, "purchase_key" character varying NULL, "current_key" character varying NULL, "status" character varying NOT NULL DEFAULT 'empty', "content" bytea NULL, "connection_id" bigint NOT NULL DEFAULT 0, "upstream_product" character varying NOT NULL DEFAULT '', "upstream_sku" character varying NOT NULL DEFAULT '', "upstream_order_id" character varying NOT NULL DEFAULT '', "connection_revision" character varying NOT NULL DEFAULT '', "origin_procurement_id" bigint NOT NULL DEFAULT 0, "expires_at" bigint NOT NULL DEFAULT 0, "delivered_count" bigint NOT NULL DEFAULT 0, "max_deliveries" bigint NOT NULL DEFAULT 0, "submitted_at" bigint NOT NULL DEFAULT 0, "next_check_at" bigint NOT NULL DEFAULT 0, "exchange_rate" double precision NOT NULL DEFAULT 1, "cost_cents" bigint NOT NULL DEFAULT 0, "last_error" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "product_delivery_sources_purchase_key_key" to table: "product_delivery_sources"
CREATE UNIQUE INDEX "product_delivery_sources_purchase_key_key" ON "product_delivery_sources" ("purchase_key");
-- Create index "productdeliverysource_current_key" to table: "product_delivery_sources"
CREATE UNIQUE INDEX "productdeliverysource_current_key" ON "product_delivery_sources" ("current_key");
-- Create index "productdeliverysource_status_next_check_at" to table: "product_delivery_sources"
CREATE INDEX "productdeliverysource_status_next_check_at" ON "product_delivery_sources" ("status", "next_check_at");
-- Create index "productdeliverysource_subsite_id_product_id_sku_id" to table: "product_delivery_sources"
CREATE INDEX "productdeliverysource_subsite_id_product_id_sku_id" ON "product_delivery_sources" ("subsite_id", "product_id", "sku_id");
